package com.gr4nt.auralauncher;

import android.animation.ValueAnimator;
import android.graphics.*;
import android.graphics.drawable.Drawable;
import android.os.Bundle;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.view.animation.PathInterpolator;
import android.widget.OverScroller;
import java.util.*;

/** Five-slot, momentum-scrolling focus carousel matching the dialer's scale/opacity profile. */
final class RecentsCarousel extends View {
    final LauncherActivity owner;final List<String> apps;final Map<String,Bitmap> previews=new HashMap<>();final Paint p=new Paint(3);final OverScroller scroller;VelocityTracker velocity;ValueAnimator snap;
    boolean disposed=false;final Map<String,Boolean> protectedFlags=new HashMap<>();float position=0,downX,downY,startPosition;boolean moved=false;int lastCentre=-1;float slot=1;final RectF card=new RectF();
    RecentsCarousel(LauncherActivity a,List<String> packages){super(a);owner=a;apps=new ArrayList<>(packages);scroller=new OverScroller(a);setFocusable(true);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);setContentDescription("Recent apps carousel");warm();}
    final Set<String> loading=new HashSet<>();
    void warm(){if(apps.isEmpty()||disposed)return;for(int delta=-2;delta<=2;delta++){String pkg=apps.get(Math.floorMod(centre()+delta,apps.size()));if(protectedFlags.containsKey(pkg)||!loading.add(pkg))continue;owner.io.execute(()->{Bitmap image=SnapshotCache.read(owner,pkg);boolean secure=SnapshotCache.protectedPreview(owner,pkg);owner.handler.post(()->{loading.remove(pkg);if(disposed){if(image!=null)image.recycle();return;}protectedFlags.put(pkg,secure);if(image!=null)previews.put(pkg,image);while(previews.size()>8){String victim=null;for(String key:previews.keySet())if(!key.equals(focused())){victim=key;break;}if(victim==null)break;Bitmap old=previews.remove(victim);protectedFlags.remove(victim);if(old!=null)old.recycle();}invalidate();});});}}

    int centre(){return apps.isEmpty()?0:Math.floorMod(Math.round(position),apps.size());}
    String focused(){return apps.isEmpty()?null:apps.get(centre());}
    @Override protected void onDraw(Canvas canvas){if(apps.isEmpty()){p.setColor(owner.ink());p.setTextAlign(Paint.Align.CENTER);p.setTextSize(owner.dp(20));canvas.drawText("No recent apps",getWidth()/2f,getHeight()/2f,p);return;}float cw=getWidth()*.66f,ch=Math.min(getHeight()*.80f,cw*1.65f);slot=(getWidth()-.66f*cw)/4;float base=getHeight()/2f;int middle=Math.round(position);List<Integer> offsets=new ArrayList<>(Arrays.asList(-2,-1,0,1,2));offsets.sort((x,y)->Float.compare(Math.abs(x-(position-middle)),Math.abs(y-(position-middle))));Set<Integer> unique=new HashSet<>();List<Integer> visible=new ArrayList<>();for(int delta:offsets)if(unique.add(Math.floorMod(middle+delta,apps.size())))visible.add(delta);visible.sort((x,y)->Float.compare(Math.abs(y-(position-middle)),Math.abs(x-(position-middle))));Set<Integer> drawn=new HashSet<>();
        for(int delta:visible){int logical=middle+delta,index=Math.floorMod(logical,apps.size());if(drawn.contains(index))continue;drawn.add(index);String pkg=apps.get(index);Catalog.App app=owner.catalog.byPackage.get(pkg);if(app==null)continue;float distance=logical-position,scale=WorkspaceRules.scale(distance),alpha=WorkspaceRules.opacity(distance);canvas.save();canvas.saveLayerAlpha(0,0,getWidth(),getHeight(),(int)(255*alpha));canvas.translate(getWidth()/2f+distance*slot,base+Math.abs(distance)*owner.dp(9));canvas.scale(scale,scale);card.set(-cw/2,-ch/2,cw/2,ch/2);p.setColor(Color.rgb(23,32,46));p.setShadowLayer(owner.dp(14),0,owner.dp(6),0x66000000);canvas.drawRoundRect(card,owner.dp(24),owner.dp(24),p);p.clearShadowLayer();canvas.save();Path clip=new Path();clip.addRoundRect(card,owner.dp(24),owner.dp(24),Path.Direction.CW);canvas.clipPath(clip);Bitmap preview=previews.get(pkg);
            if(preview!=null){p.setAlpha(255);canvas.drawBitmap(preview,null,card,p);p.setAlpha(255);}else{p.setShader(new LinearGradient(0,-ch/2,cw,ch/2,new int[]{0xff354a60,0xff51456b},null,Shader.TileMode.CLAMP));canvas.drawRect(card,p);p.setShader(null);Drawable icon=owner.catalog.icon(app);int size=owner.dp(74);icon.setBounds(-size/2,-size/2,size/2,size/2);icon.draw(canvas);p.setColor(0xffc6d0df);p.setTextSize(owner.dp(12));p.setTextAlign(Paint.Align.CENTER);canvas.drawText(Boolean.TRUE.equals(protectedFlags.get(pkg))?"Preview protected":"App preview unavailable",0,owner.dp(70),p);}
            p.setColor(0xdd142034);canvas.drawRect(-cw/2,-ch/2,cw/2,-ch/2+owner.dp(50),p);p.setColor(Color.WHITE);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextAlign(Paint.Align.LEFT);p.setTextSize(owner.dp(15));String name=owner.store.name(pkg,app.label);while(name.length()>1&&p.measureText(name)>cw-owner.dp(30))name=name.substring(0,name.length()-2)+"…";canvas.drawText(name,-cw/2+owner.dp(15),-ch/2+owner.dp(31),p);canvas.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(owner.dp(1));p.setColor(0x88ffffff);canvas.drawRoundRect(card,owner.dp(24),owner.dp(24),p);p.setStyle(Paint.Style.FILL);canvas.restore();canvas.restore();}
    }
    @Override public boolean onTouchEvent(MotionEvent event){if(apps.isEmpty())return true;if(event.getActionMasked()==MotionEvent.ACTION_DOWN){if(snap!=null)snap.cancel();scroller.abortAnimation();downX=event.getX();downY=event.getY();startPosition=position;moved=false;velocity=VelocityTracker.obtain();velocity.addMovement(event);return true;}if(velocity!=null)velocity.addMovement(event);if(event.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=event.getX()-downX;if(Math.abs(dx)>owner.dp(8)){moved=true;position=startPosition-dx/Math.max(1,slot);tick();invalidate();}return true;}if(event.getActionMasked()==MotionEvent.ACTION_UP){float dy=event.getY()-downY;if(dy<-owner.dp(75)&&Math.abs(event.getX()-downX)<owner.dp(65)){dismissFocused();}else if(!moved){Catalog.App app=owner.catalog.byPackage.get(focused());if(app!=null)owner.launch(app,0);}else{velocity.computeCurrentVelocity(1000);float speed=-velocity.getXVelocity();if(Math.abs(speed)>owner.dp(250)){scroller.fling(Math.round(position*slot),0,(int)speed,0,-1000000,1000000,0,0);postInvalidateOnAnimation();}else settle();}if(velocity!=null){velocity.recycle();velocity=null;}return true;}if(event.getActionMasked()==MotionEvent.ACTION_CANCEL){if(velocity!=null){velocity.recycle();velocity=null;}settle();}return true;}
    void tick(){int centre=centre();if(centre!=lastCentre){lastCentre=centre;warm();performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);}}
    void settle(){if(apps.isEmpty())return;float target=Math.round(position);snap=ValueAnimator.ofFloat(position,target);snap.setDuration(330);snap.setInterpolator(new PathInterpolator(.16f,1,.3f,1));snap.addUpdateListener(v->{position=(float)v.getAnimatedValue();tick();invalidate();});snap.start();}
    @Override public void computeScroll(){if(scroller.computeScrollOffset()){position=scroller.getCurrX()/Math.max(1,slot);tick();postInvalidateOnAnimation();}else if(!apps.isEmpty()&&Math.abs(position-Math.round(position))>.001f&&(snap==null||!snap.isRunning()))settle();}
    void dismissFocused(){String pkg=focused();if(pkg==null)return;owner.store.remove("recent",pkg);SnapshotCache.remove(owner,pkg);Bitmap bitmap=previews.remove(pkg);if(bitmap!=null)bitmap.recycle();apps.remove(centre());position=apps.isEmpty()?0:Math.floorMod(Math.round(position),apps.size());invalidate();}
    @Override public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);String pkg=focused();Catalog.App app=owner.catalog.byPackage.get(pkg);info.setContentDescription(app==null?"No recent apps":"Recent app: "+owner.store.name(pkg,app.label));info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_CLICK);}
    @Override public boolean performAccessibilityAction(int action,Bundle args){if(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD||action==AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD){position+=action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD?1:-1;settle();return true;}if(action==AccessibilityNodeInfo.ACTION_CLICK){Catalog.App app=owner.catalog.byPackage.get(focused());if(app!=null)owner.launch(app,0);return true;}return super.performAccessibilityAction(action,args);}
    @Override protected void onDetachedFromWindow(){disposed=true;if(snap!=null)snap.cancel();scroller.abortAnimation();for(Bitmap bitmap:previews.values())if(!bitmap.isRecycled())bitmap.recycle();previews.clear();super.onDetachedFromWindow();}
}
